patch:
diff --git a/src/cache.mjs b/src/cache.mjs
index 2fe3ea5..e66d359 100644
--- a/src/cache.mjs
+++ b/src/cache.mjs
@@ -5,12 +5,18 @@ export function createCache(load, { ttlMs, now }) {
   return {
     async get(key) {
       const entry = entries.get(key);
+      if (entry?.pending) return entry.pending;
       if (isFresh(entry, now())) return entry.value;
-      const pending = load(key);
-      entries.set(key, { value: pending, expiresAt: now() + ttlMs });
-      const value = await pending;
-      entries.set(key, { value, expiresAt: now() + ttlMs });
-      return value;
+      const pending = Promise.resolve(load(key));
+      entries.set(key, { pending });
+      try {
+        const value = await pending;
+        entries.set(key, { value, expiresAt: now() + ttlMs });
+        return value;
+      } catch (error) {
+        entries.delete(key);
+        throw error;
+      }
     },
   };
 }
diff --git a/src/entry.mjs b/src/entry.mjs
index 2797db0..3f35ab1 100644
--- a/src/entry.mjs
+++ b/src/entry.mjs
@@ -1,3 +1,3 @@
 export function isFresh(entry, now) {
-  return Boolean(entry) && entry.expiresAt >= now;
+  return Boolean(entry) && entry.expiresAt > now;
 }
